import{_ as t}from"./chunks/performance-trends.BEEamWXJ.js";import{_ as a,o as r,c as s,ak as o}from"./chunks/framework.sV-XtlWr.js";const f=JSON.parse('{"title":"Slow tests & wasted time","description":"","frontmatter":{"title":"Slow tests & wasted time","lang":"en-US"},"headers":[],"relativePath":"features/slow-tests.md","filePath":"features/slow-tests.md","lastUpdated":1788707566000}'),i={name:"features/slow-tests.md"};function n(l,e,d,h,u,m){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="slow-tests-wasted-time" tabindex="-1">Slow tests &amp; wasted time <a class="header-anchor" href="#slow-tests-wasted-time" aria-label="Permalink to &quot;Slow tests &amp; wasted time&quot;">​</a></h1><p>The test list tells you what failed; it doesn&#39;t tell you where the <strong>minutes</strong> go. The <strong>Performance</strong> view on a project surfaces the slow tests, the trends behind them, and the time you could reclaim.</p><h2 id="duration-trends" tabindex="-1">Duration trends <a class="header-anchor" href="#duration-trends" aria-label="Permalink to &quot;Duration trends&quot;">​</a></h2><p>Average and <strong>P90</strong> duration over time, so a few slow outliers don&#39;t hide a real regression (a rising P90 with a flat average is a tail getting worse). <strong>Slowest tests</strong> ranks the top offenders by duration.</p><figure><img src="'+t+'" alt="Performance tab showing the duration trend chart and slowest-tests table"><figcaption>The Performance view — average and P90 duration trends over time, followed by a ranked table of the slowest tests.</figcaption></figure><h2 id="timeout-opportunities" tabindex="-1">Timeout opportunities <a class="header-anchor" href="#timeout-opportunities" aria-label="Permalink to &quot;Timeout opportunities&quot;">​</a></h2><p>Tests whose configured per-test timeout dwarfs their real p95 duration — so a hang or failure waits far longer than it needs to — plus tests still carrying a stale <code>test.slow()</code> mark they no longer need. Each row suggests a tighter timeout (or removing the mark) and the time reclaimable per failing run, ranked by impact.</p><p>This reads the per-test timeout the <a href="/guide/reporter.html#per-test-timeout">reporter captures</a>; runs reported before that shipped still surface stale <code>test.slow()</code> marks from annotations and durations alone. The thresholds are tunable via <code>PUT /api/settings/timeout-hygiene</code>.</p><h2 id="network-and-web-vitals" tabindex="-1">Network and Web Vitals <a class="header-anchor" href="#network-and-web-vitals" aria-label="Permalink to &quot;Network and Web Vitals&quot;">​</a></h2><ul><li><strong>Network analysis</strong> — slow API calls grouped by method and normalized route (e.g. <code>/api/users/:id</code>), for a run picked from the tab.</li><li><strong>Browser Web Vitals</strong> — TTFB, DOMContentLoaded, FCP and more, with color-coded thresholds.</li></ul><p>Both require the <a href="/guide/capture-fixtures.html">capture fixtures</a> in your test setup — without them the reporter has no network timings or Web Vitals to aggregate.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/capture-fixtures.html">Capture fixtures</a> — the test-side setup behind network analysis and Web Vitals</li><li><a href="./flaky-tests.html">Flaky tests</a> — flaky scoring costs wasted CI minutes the same way</li><li><a href="./analytics.html">Analytics</a> — wasted CI minutes and slow endpoints across every project</li><li><a href="/guide/reporter.html#per-test-timeout">Reporter</a> — how the per-test timeout is captured</li></ul>',13)])])}const w=a(i,[["render",n]]);export{f as __pageData,w as default};
